// 1991: Project 'Oak' begins.
// 1995: Officially released as Java 1.0.
// Today: Billions of devices run Java globally.

// Step 1: The Compiler (Creates the hardware-agnostic .class file)
> javac ParhoMateEngine.java

// Step 2: The JVM Interpreter (Executes on your specific physical hardware)
> java ParhoMateEngine

// 1. JDK (Java Development Kit) - For the Architect
// Contains the compiler (javac), debuggers, and the JRE.
> javac SystemEngine.java  // Converts code to Bytecode

// 2. JRE (Java Runtime Environment) - For the User
// Contains the JVM and the core class libraries needed to run apps.

// 3. JVM (Java Virtual Machine) - The Execution Engine
// Lives inside the JRE. Interprets Bytecode and executes it on your OS.
> java SystemEngine        // Triggers the JVM to run the Bytecode

// THE CLASS (The Paper Blueprint)
class Car { 
    int doors = 4;
    void honkHorn() { System.out.println("Beep!"); }
}

// THE OBJECT (The Physical Engine in Memory)
// The 'new' keyword commands the JVM to allocate physical RAM for the object!
Car myToyota = new Car(); 
Car myHonda = new Car();

package com.parhomate.core; // Namespace: Prevents naming collisions in large apps

public class SystemEngine { 
    // The Class Scope.
    // ALL of your code, variables, and methods MUST go inside here.
    // If you write logic outside these curly braces, the compiler crashes.
}

public static void main(String[] args) {
    // The JVM starts executing code right here.
    System.out.println("System Booting...");
}

// The 'ln' stands for 'line new'
System.out.print("Booting..."); 
System.out.println(" Done!");
// Output: Booting... Done!

System.out.println("System Ready.");
// Final Output:
// Booting... Done!
// System Ready.

// 1. SYNTAX ERROR (Compile-Time Blocker)
int score = 100 // ERROR: Missing semicolon! The compiler refuses to build the Bytecode.

// 2. LOGICAL ERROR (The Silent Failure)
// Calculating an average, but the architect forgot PEMDAS parentheses.
double average = 10 + 20 / 2; // EXECUTES FINE, but yields 20.0 instead of 15.0.

// 3. RUNTIME ERROR (The Fatal Exception)
// The compiler builds the Bytecode, but the JVM crashes trying to execute it in RAM.
int mathCrash = 50 / 0; // Throws an ArithmeticException and halts the program!

// 1. LEXICAL COMPILER LAWS (Breaking these crashes the build)
// int 3rdPlace = 10;   // FATAL ERROR: Identifiers cannot start with a digit!
// double class = 4.0;  // FATAL ERROR: Identifiers cannot use reserved keywords!
int place3 = 10;        // SUCCESS

// 2. PascalCase (Strictly for Blueprints/Classes)
// Rule: The first letter of EVERY word is Capitalized.
class ParhoMateEngine { }
class StudentProfile { }

// 3. camelCase (Strictly for Actions & Storage/Variables)
// Rule: First letter is lowercase, subsequent words are Capitalized.
int myMarks = 100;
void calculateFinalScore() { }

// 4. UPPER_SNAKE_CASE (Strictly for Locked Data/Constants)
// Rule: ALL CAPS, with words separated by underscores.
final double PI_VALUE = 3.14159;
final int MAX_CAPACITY = 10000;

// THE HARDWARE ENGINE
// 1. Control Unit (CU): Manages how data moves and fetches instructions.
// 2. ALU: Arithmetic Logic Unit handles mathematical/logical comparisons.
// 3. Registers: The absolute fastest, temporary memory directly inside the CPU.

// 1. PRIMITIVE VARIABLE (Raw data directly on the Stack)
int age = 21;

// 2. REFERENCE VARIABLE (Pointer on Stack, Object payload on the Heap)
Scanner input = new Scanner(System.in);

// THE ARCHITECT'S LAW: References have behaviors, Primitives do NOT!
input.nextInt();   // SYSTEM SUCCESS: The Scanner object has built-in methods.
// age.toString(); // COMPILER CRASH: Primitives are raw data; they have no methods!

// 1. byte (8 bits): The smallest box.
byte tinyNum = 127; 

// 2. short (16 bits): For small counters.
short smallNum = 32767; 

// 3. int (32 bits): The industry standard default.
int score = 2147483647; 

// 4. long (64 bits): For massive numbers.
long debt = 9223372036854775807L; // Requires an 'L' at the end!

// 1. float (32 bits / 4 bytes): Standard precision.
float temperature = 98.6f; // Requires an 'f' at the end!

// 2. double (64 bits / 8 bytes): High precision (Industry standard).
double atomSize = 0.00000000532;

// 3. Scientific Notation (E-notation)
// Supported natively by the double data type!
double lightSpeed = 3.0e10; // Evaluates to 3.0 x 10^10 (30,000,000,000.0)

// Method 1: Two-Step (Declaration, then Initialization)
int age;
age = 21;

// Method 2: Single-Line (The Industry Standard)
double cashAmount = 150.75;

// Method 3: Immutability (The 'final' Keyword)
// Locks the memory address so the data can NEVER be overwritten.
final double PI_VALUE = 3.14159;

// UPDATING (Assignment Statement)
// Later in the program, you can overwrite standard variables:
cashAmount = 200.00; // The 150.75 is permanently deleted from RAM.

// 1. THE TEXTUAL FAMILY (char)
// Occupies 16 bits (2 bytes) of RAM. Wrapped strictly in SINGLE quotes.
char userGrade = 'A';
char securitySymbol = '$';

// 2. THE LOGICAL FAMILY (boolean)
// Stores binary states: strictly 'true' or 'false'. Default state is false.
boolean isSystemEncryptionActive = true;
boolean dataPipelineCompressed = false;

// Pro-Architect Tip: Never wrap boolean states in quotes! 
// boolean flag = "true"; -> FATAL ERROR: "true" is an object String, not a primitive boolean state.
